// Build Quorum heartbeat body + signing inputs.
// No require()/import of Node modules — Crypto nodes hash and HMAC.
//
// Config (prefer n8n process env; edit literals below if $env is blocked):
//   QUORUM_WORKFLOW_ID, QUORUM_KEY_ID, QUORUM_BASE_URL
// HMAC secret:
//   - Default export: Crypto HMAC typeVersion 1 Secret = {{ $env.QUORUM_HMAC_SECRET }}
//   - Or Crypto credentials (Crypto node v2, n8n >= 2.7): set QUORUM_USE_CRYPTO_CREDENTIAL=1
// On n8n 2.x, env path also needs N8N_BLOCK_ENV_ACCESS_IN_NODE=false.

const CONFIG = {
  workflowId: String($env.QUORUM_WORKFLOW_ID || '').trim(),
  keyId: String($env.QUORUM_KEY_ID || '').trim(),
  baseUrl: String($env.QUORUM_BASE_URL || '').trim(),
  hmacSecret: String($env.QUORUM_HMAC_SECRET || '').trim(),
  useCryptoCredential: String($env.QUORUM_USE_CRYPTO_CREDENTIAL || '').trim() === '1',
};

// Optional post-import overrides when $env access is blocked:
// CONFIG.workflowId = 'YOUR_QUORUM_WORKFLOW_ID';
// CONFIG.keyId = 'YOUR_KEY_ID';
// CONFIG.baseUrl = 'http://host.docker.internal:3000';
// CONFIG.useCryptoCredential = true;

function requireValue(label, value) {
  const s = value == null ? '' : String(value).trim();
  if (!s || s.startsWith('REPLACE_') || s.startsWith('YOUR_')) {
    throw new Error(
      `Missing ${label}. Set it on the n8n process env (and N8N_BLOCK_ENV_ACCESS_IN_NODE=false on n8n 2.x), or edit CONFIG in Prepare Heartbeat.`,
    );
  }
  return s;
}

const workflowId = requireValue('QUORUM_WORKFLOW_ID', CONFIG.workflowId);
const keyId = requireValue('QUORUM_KEY_ID', CONFIG.keyId);
const baseUrl = requireValue('QUORUM_BASE_URL', CONFIG.baseUrl).replace(/\/+$/, '');

if (!CONFIG.useCryptoCredential && !CONFIG.hmacSecret) {
  throw new Error(
    'Missing QUORUM_HMAC_SECRET (set n8n env for the Crypto HMAC Secret expression, or set QUORUM_USE_CRYPTO_CREDENTIAL=1 when using Crypto credentials on Crypto node v2)',
  );
}

const path = `/api/v1/workflows/${workflowId}/heartbeats`;

const bodyObj = {
  schemaVersion: 1,
  executedAt: new Date().toISOString(),
  status: 'success',
  itemsProcessed: 1,
  externalExecutionRef: `n8n-${Date.now()}`,
};
const bodyRaw = JSON.stringify(bodyObj);
const timestampSeconds = String(Math.floor(Date.now() / 1000));
const idempotencyKey = `n8n-${timestampSeconds}-${Math.random().toString(16).slice(2)}`;

return [{
  json: {
    url: `${baseUrl}${path}`,
    path,
    bodyRaw,
    keyId,
    timestampSeconds,
    idempotencyKey,
  },
}];

// Canonical signing payload (must match Quorum heartbeat-hmac.ts):
// ["POST", path, timestampSeconds, idempotencyKey, bodySha256Hex].join("\n")
const bodySha256Hex = $json.bodySha256Hex;
if (!bodySha256Hex || typeof bodySha256Hex !== 'string') {
  throw new Error('Missing bodySha256Hex from Hash Body SHA256 Crypto node');
}

const signingPayload = [
  'POST',
  $json.path,
  $json.timestampSeconds,
  $json.idempotencyKey,
  bodySha256Hex,
].join('\n');

return [{
  json: {
    ...$json,
    signingPayload,
  },
}];
